//! The release workflow reads `callisto --format json release pending` with jq (`.pending[0].source`).
//! A renamed key would read as "nothing pending" and skip a stuck release, so the real output is pinned here.
#[path = "common/release_harness.rs"]
mod release_harness;

use release_harness::*;

#[test]
fn release_pending_json_carries_the_keys_the_workflow_reads() {
    let (dir, release_commit) = release_commit_fixture();
    let out = callisto(dir.path(), &["release", "pending"]);
    assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
    let report: serde_json::Value = serde_json::from_slice(&out.stdout).unwrap();

    // `.pending[0].source` is what callisto-release.yml selects as the release to finish.
    assert_eq!(report["pending"][0]["source"], release_commit, "{report}");
    assert_eq!(
        report["pending"][0]["packages"][0]["package"], "cargo/core-crate",
        "{report}"
    );
    assert_eq!(report["pending"][0]["packages"][0]["version"], "0.2.0", "{report}");
    let missing = report["pending"][0]["missing"].as_array().expect("missing is an array");
    assert!(
        missing
            .iter()
            .any(|gap| gap.as_str().is_some_and(|gap| gap.contains("core-crate@0.2.0"))),
        "{report}"
    );
}

#[test]
fn release_pending_json_is_an_empty_list_when_every_release_finished() {
    let (dir, _) = release_commit_fixture();
    git(dir.path(), &["tag", "-a", "-m", "release", "core-crate@0.2.0"]);
    let out = callisto(dir.path(), &["release", "pending"]);
    assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
    let report: serde_json::Value = serde_json::from_slice(&out.stdout).unwrap();
    assert_eq!(report["pending"], serde_json::json!([]), "{report}");
}
//! End-to-end coverage for the severity-validation message: `callisto add --package name:severity` must list
//! `none` among the allowed values, since `Severity` accepts it. The unit tests in `add.rs` call `parse_severity`
//! directly; these prove the wording reaches the real CLI's stderr/stdout, exactly what an operator sees when
//! they mistype a severity.
//!
//! Lock contention is covered by unit tests against a real `fs2` file lock; reproducing it at the CLI level
//! needs a second concurrent process.

use std::path::Path;
use std::process::Command;

fn callisto_bin() -> &'static str {
    env!("CARGO_BIN_EXE_callisto")
}

fn setup_minimal_workspace() -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();

    callisto_fixtures::git::init_repo(root);

    std::fs::write(
        root.join("Cargo.toml"),
        "[workspace]\nmembers = [\"crates/demo\"]\nresolver = \"2\"\n",
    )
    .unwrap();
    std::fs::create_dir_all(root.join("crates/demo/src")).unwrap();
    std::fs::write(
        root.join("crates/demo/Cargo.toml"),
        "[package]\nname = \"demo\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
    )
    .unwrap();
    std::fs::write(root.join("crates/demo/src/lib.rs"), "pub fn hello() {}\n").unwrap();
    std::fs::write(root.join("callisto.toml"), "").unwrap();

    assert!(Command::new("git")
        .args(["add", "-A"])
        .current_dir(root)
        .status()
        .unwrap()
        .success());
    assert!(Command::new("git")
        .args(["commit", "-q", "-m", "Initial commit"])
        .current_dir(root)
        .status()
        .unwrap()
        .success());

    dir
}

